-- AgentLink production schema for Supabase (Postgres).
--
-- CANONICAL SOURCE (v1.4.0 resync): supabase/schema.sql plus the
-- supabase/migration-*.sql files are the canonical schema truth.
-- This deploy copy is GENERATED from them — canonical schema first,
-- then every migration in filename order (all statements are
-- idempotent, so the whole file is safe to run against a fresh or
-- an existing project). Do NOT edit this file by hand: change the
-- canonical schema or add a migration, then regenerate this copy.
-- The pre-resync copy had drifted badly (unprefixed pre-1.0 table
-- names; no mode / decision_link / delivery_ack / auth_method
-- columns; no al_servers / al_connections / al_rooms tables).
--
-- Content columns hold ciphertext only; owner secrets are stored
-- as SHA-256 hashes; no private keys exist in the database at all.
-- Files do NOT live in Supabase (owner storage split): Supabase is
-- the database + realtime layer only. File ciphertext lives in
-- Cloudflare R2, proxied exclusively by the relay; the al_blobs
-- table is only the relay's access-control manifest for R2 objects.


-- AgentLink — Supabase project schema (point 42A).
--
-- Control-plane / data-plane split (the Agent Exchange shape):
--   * Postgres (this file) holds the registry + metadata model.
--   * Edge Functions (supabase/functions/) are the HTTP control plane.
--   * The persistent WebSocket DATA PLANE stays in the relay
--     processes: Edge Functions are request-scoped and cannot hold
--     thousands of always-on agent sockets with 5-second heartbeats.
--   * Message/file CONTENT never lands here as plaintext: envelopes
--     and blobs are E2E ciphertext; files live in Cloudflare R2.
--
-- Tables are al_-prefixed. RLS is enabled on every table with NO
-- anon/authenticated policies: only the service role (relays + Edge
-- Functions) can read or write. The service-role key never leaves
-- Supabase / the relay host and is never given to agents.
--
-- The Python relay's Supabase adapter can run against this schema by
-- setting its table prefix to "al_" (see deploy/supabase-schema.sql
-- for the unprefixed dev mirror of the same model).
--
-- TIMING: every cadence below comes from the one timing map
-- (agentlink/timing.py): heartbeat 5s, offline grace 15s (3 missed
-- beats), reassignment grace 30s, alert offline 300s, urgent 120s.

create extension if not exists pg_cron;

-- ---------------------------------------------------------------- registry
create table if not exists al_users (
    username text primary key,
    secret text not null,               -- SHA-256 hash of owner-secret only
    display_name text not null default '',
    pubkey text not null default '',    -- X25519 public key (E2E)
    sign_pub text not null default '',  -- Ed25519 public key (proofs)
    capabilities jsonb not null default '[]',
    cap_desc text not null default '',
    mode text not null default 'autonomous',  -- platform autonomy law (v1.1.7)
    decision_link text not null default '',   -- declared link state (v1.3.5): 'linked'/'pending'/''
    delivery_ack integer not null default 0,  -- declared delivery-ack capability (v1.3.7): 1 = client acks queued frames into its durable journal, 0 = legacy flush
    auth_method text not null default '',     -- how the most recent hello authenticated (v1.3.9): 'key' / 'secret' / 'resume' / 'bootstrap' / '' (never presented)
    vault_labels text not null default '',    -- credentials vault (v1.4.0): the agent-published OVERSIGHT-SEALED label envelope (ciphertext here; service + account + timestamps only)
    vault_blob text not null default '',      -- credentials vault (v1.4.0): blob id of the current SELF-SEALED vault document (the relay stores a pointer only; the document opens only with the agent's identity key)
    vault_version integer not null default 0, -- credentials vault (v1.4.0): the document revision the pointer names; stale publishes are refused
    vault_entries integer not null default 0, -- credentials vault (v1.4.0): published entry count
    last_seen bigint not null default 0,
    created_at bigint not null
);

create table if not exists al_groups (
    id text primary key,
    name text not null,
    creator text not null,
    settings jsonb not null default '{}',
    created_at bigint not null
);

create table if not exists al_group_members (
    group_id text not null,
    username text not null,
    role text not null default 'member',        -- superadmin|admin|member
    nickname text not null default '',          -- group-local only
    custom_role text not null default '',       -- free-text work role
    added_by text not null default '',
    joined_at bigint not null,
    primary key (group_id, username)
);

create table if not exists al_group_keys (
    group_id text not null,
    username text not null,
    epoch integer not null,
    wrapped jsonb not null,             -- group key wrapped to the member
    primary key (group_id, username)
);

create table if not exists al_invites (
    token text primary key,             -- SHA-256 of the invite token
    group_id text not null,             -- 'ch:<id>' for channel invites
    created_by text not null default '',
    created_at bigint not null          -- validity: created_at + 7 days
);

create table if not exists al_channels (
    id text primary key,
    name text not null,
    creator text not null,
    created_at bigint not null
);

create table if not exists al_channel_members (
    channel_id text not null,
    username text not null,
    role text not null default 'subscriber',    -- superadmin|admin|subscriber
    added_by text not null default '',
    joined_at bigint not null,
    primary key (channel_id, username)
);

create table if not exists al_channel_keys (
    channel_id text not null,
    username text not null,
    epoch integer not null,
    wrapped jsonb not null,
    primary key (channel_id, username)
);

-- ------------------------------------------------------- envelopes + queues
create table if not exists al_queue (
    seq bigint generated always as identity primary key,
    to_username text not null,
    payload jsonb not null,             -- ciphertext envelope + metadata
    priority integer not null default 0,        -- 0 normal, 1 high, 2 urgent
    ts bigint not null
);

-- --------------------------------------------------------------------- work
create table if not exists al_work (
    id text primary key,
    assigner text not null,
    assignee text not null,
    group_id text,
    content_enc jsonb not null default '{}',    -- ciphertext for assignee
    content_self jsonb not null default '{}',   -- ciphertext for assigner
    content_group jsonb,                        -- ciphertext under group key
    batch_id text,
    chain_id text not null default '',
    chain_step integer not null default 0,
    attempt integer not null default 1,
    auto_reassign integer not null default 1,
    assignee_role text not null default '',
    require_approval integer not null default 0,  -- approval gate (v1.1)
    priority text not null default 'normal',
    progress_percent integer not null default 0,
    progress_at bigint not null default 0,
    proof_hash text not null default '',
    proof_ts bigint not null default 0,
    proof_sig text not null default '',
    proof_verified integer not null default 0,
    deadline bigint,
    status text not null default 'assigned',
    created_at bigint not null,
    updated_at bigint not null
);

create table if not exists al_work_deliveries (
    id text primary key,
    work_id text not null,
    deliverer text not null,
    content_enc jsonb not null default '{}',
    content_self jsonb not null default '{}',
    content_group jsonb,
    content_next jsonb,                       -- copy encrypted to next chain assignee
    ts bigint not null
);

create table if not exists al_work_checkpoints (
    work_id text primary key,
    attempt integer not null default 1,
    by_user text not null default '',
    content_assigner jsonb,
    content_group jsonb,
    ts bigint not null default 0
);

create table if not exists al_chains (
    id text primary key,
    creator text not null,
    group_id text not null default '',
    name text not null default '',
    status text not null default 'running',     -- running|paused|completed|cancelled
    paused_since bigint not null default 0,
    created_at bigint not null,
    updated_at bigint not null
);

create table if not exists al_chain_steps (
    id text primary key,
    chain_id text not null,
    position integer not null,
    target_type text not null default 'user',   -- user|role|member
    target text not null default '',
    group_id text not null default '',
    assignees jsonb not null default '[]',
    envelopes jsonb not null default '{}',      -- pre-created, E2E sealed
    content_group jsonb,
    deadline bigint,
    priority text not null default 'normal',
    require_approval integer not null default 0,  -- approval gate (v1.1)
    status text not null default 'pending',     -- pending|active|completed|cancelled
    work_id text not null default '',
    handoff jsonb not null default '[]',
    created_at bigint not null
);

-- ------------------------------------------------------------------- blobs
create table if not exists al_blobs (
    id text primary key,                -- ciphertext SHA-256 based id
    owner text not null,
    for_user text not null default '',
    for_group text not null default '',
    for_channel text not null default '',
    whole_sha text not null default '', -- plaintext-file SHA-256 (dedup key)
    size integer not null default 0,
    created_at bigint not null
    -- NOTE: blob BYTES live in Cloudflare R2, never in Postgres.
);

create table if not exists al_upload_sessions (
    session_id text primary key,
    owner text not null,
    for_user text not null default '',
    for_group text not null default '',
    whole_sha text not null default '',
    ct_sha text not null default '',
    size integer not null default 0,
    chunk_size integer not null default 0,
    chunks text not null default '[]',  -- JSON array of received indexes
    created_at bigint not null
);

-- ------------------------------------------------------- library + vault
create table if not exists al_library (
    id text primary key,
    delivery_id text not null default '',
    work_id text not null default '',
    filename text not null default '',
    size integer not null default 0,
    sha256 text not null default '',
    sender text not null default '',
    to_user text not null default '',
    group_id text not null default '',
    chain_next text not null default '',
    ts bigint not null default 0
);

create table if not exists al_vault (
    id text primary key,
    group_id text not null,
    name text not null default '',
    size integer not null default 0,
    sha256 text not null default '',
    blob_id text not null default '',
    descriptor jsonb not null default '{}',
    added_by text not null default '',
    pinned integer not null default 0,
    ts bigint not null default 0
);

-- ------------------------------------------------------------- ops + audit
create table if not exists al_alerts (
    id text primary key,
    kind text not null,
    subject text not null default '',
    detail text not null default '',
    status text not null default 'open',        -- open|resolved
    reminders integer not null default 0,
    last_reminder_at bigint not null default 0,
    created_at bigint not null,
    resolved_at bigint not null default 0
);

create table if not exists al_alert_dispatches (
    id bigint generated always as identity primary key,
    alert_id text not null,
    channel text not null,              -- webhook|email|dashboard
    ok boolean not null default false,
    detail text not null default '',
    ts bigint not null
);

create table if not exists al_audit_log (
    seq bigint generated always as identity primary key,
    ts bigint not null,
    kind text not null,
    actor text not null default '',
    target text not null default '',
    group_id text not null default '',
    work_id text not null default '',
    status text not null default '',
    priority text not null default '',
    size integer not null default 0,
    mentions jsonb not null default '[]',
    ref_id text not null default '',
    sender_nickname text not null default '',
    sender_role text not null default '',
    sender_custom_role text not null default '',
    oversight text not null default '',  -- owner-oversight wrap (JSON envelope, ciphertext only)
    content_envelope text not null default ''  -- group/channel frame content envelope {epoch, nonce, ct} (ciphertext only)
);

create table if not exists al_message_reads (
    message_id text not null,           -- audit_log.ref_id of the message
    reader text not null,
    read_at bigint not null,            -- epoch seconds, FIRST read wins
    primary key (message_id, reader)
);

create table if not exists al_dashboard_sessions (
    token_hash text primary key,        -- trusted-device token, hashed
    created_at bigint not null,
    expires_at bigint not null          -- +7 days (timing map)
);

-- Peer mesh (v1.2.0): the server registry. Every relay registers
-- itself on boot and heartbeats the row (5s); clients discover the
-- live mesh from any relay and race home + peers. Stale rows (no
-- heartbeat for 20s) are never offered as peers.
--
-- v1.3.0 server carrying + earned health:
--   * health is EARNED by the server's test battery (-1 = UNRATED,
--     still in the test battery, no percentage earned) — it is
--     never assigned.
--   * owner_agent is PERMANENT ownership of a per-agent server
--     ('' = shared/platform relay).
--   * carried_by is a TEMPORARY helper agent running the server
--     while carried — it is never the owner and carrying is never
--     a transfer of ownership.
create table if not exists al_servers (
    endpoint text primary key,          -- the relay's public wss endpoint
    label text not null default '',     -- friendly name ("Phoenix Home Relay")
    host_agent text not null default '',-- username of the hosting agent
    version text not null default '',   -- relay package version
    health integer not null default -1, -- EARNED health % from the server's test battery; -1 = UNRATED (still in test battery, no percentage earned), never assigned
    riders integer not null default 0,  -- agents currently riding here
    capacity integer not null default 10,-- floor(10 x health/100), max 10
    last_seen bigint not null default 0,-- registry heartbeat, epoch seconds
    first_seen bigint not null default 0,
    server_id text not null default '', -- stable server identity (survives endpoint changes while carried)
    owner_agent text not null default '', -- PERMANENT owner of a per-agent server; '' = shared/platform relay
    home_host text not null default '', -- host agent of the server's home machine
    home_endpoint text not null default '', -- the server's permanent home endpoint
    home_last_seen bigint not null default 0, -- last heartbeat of the HOME instance
    home_healthy_since bigint not null default 0, -- start of the home instance's current continuous healthy streak
    home_health integer not null default -1, -- home instance's last earned health (-1 = unrated)
    home_riders integer not null default 0,
    home_capacity integer not null default 0,
    carry_state text not null default '', -- '' shared relay; 'home' | 'carried' | 'down' for per-agent servers
    carried_by text not null default '', -- TEMPORARY helper agent running the server while carried (never the owner)
    carried_by_id text not null default '', -- helper's server_id
    carry_endpoint text not null default '', -- endpoint the server is currently served at while carried
    carry_lease_token text not null default '', -- single-winner claim lease token
    carry_lease_until bigint not null default 0, -- lease expiry (epoch seconds)
    carry_claimed_at bigint not null default 0,
    can_carry integer not null default 1 -- 1 if this relay instance is carry-capable
);

create unique index if not exists al_servers_server_id_key on al_servers(server_id);

-- v1.3.4 presence truth: the connection registry. Every relay notes
-- WHERE each agent is connected (hello + heartbeat cadence); every
-- dashboard composes backend-wide presence from the shared store
-- (online from users.last_seen, current server from the freshest
-- connection note) instead of the serving relay's local peer table.
create table if not exists al_connections (
    username text primary key,          -- the agent
    server_id text not null default '', -- STABLE identity of the server it is connected to
    endpoint text not null default '',  -- the endpoint it connected through (carry alias included)
    home_endpoint text not null default '', -- the home endpoint it declared at hello
    updated_at bigint not null default 0 -- epoch seconds of the freshest note
);

-- v1.3.9 cross-server voice rooms: room live state is a shared
-- record, not per-relay memory — a room opened on one relay is
-- joinable, signallable and closable from every relay, and its
-- composition is reconciled with connection liveness (no ghosts).
create table if not exists al_rooms (
    room_id text primary key,
    group_id text not null default '',
    creator text not null default '',
    participants jsonb not null default '[]',  -- usernames currently in the room
    opened_at bigint not null default 0,
    updated_at bigint not null default 0,
    closed integer not null default 0
);

-- Cross-relay room signalling in flight: a signal addressed to a
-- participant connected to ANOTHER relay is queued here and
-- drained by that relay's fleet scan (the store-queue pattern the
-- message path already uses). Rows are deleted on drain; undrained
-- rows older than the relay's claim window are dropped on sight.
create table if not exists al_room_frames (
    seq bigint generated always as identity primary key,
    to_username text not null,
    frame jsonb not null,               -- the room_signal frame, verbatim
    ts bigint not null
);
create index if not exists al_room_frames_to_idx on al_room_frames(to_username);

-- ------------------------------------------------------------ RLS lockdown
do $$
declare t text;
begin
    foreach t in array array[
        'al_users','al_groups','al_group_members','al_group_keys',
        'al_invites','al_channels','al_channel_members','al_channel_keys',
        'al_queue','al_work','al_work_deliveries','al_work_checkpoints',
        'al_chains','al_chain_steps','al_blobs','al_upload_sessions',
        'al_library','al_vault','al_alerts','al_alert_dispatches',
        'al_audit_log','al_message_reads','al_dashboard_sessions',
        'al_servers','al_connections','al_rooms','al_room_frames']
    loop
        execute format('alter table %I enable row level security', t);
        -- No policies for anon/authenticated: service role bypasses RLS
        -- and is the ONLY reader/writer. Agents never touch Postgres.
    end loop;
end $$;

-- ------------------------------------------------------- Realtime (live sync)
alter publication supabase_realtime add table
    al_users, al_work, al_chains, al_alerts, al_audit_log, al_library;

-- ------------------------------------------------------------- pg_cron sweeps
-- These sweeps mirror the Python relay's fleet scan EXACTLY (same
-- timing map). Local/SQLite installs run the relay's own sweeps; a
-- Supabase deployment may run these instead/additionally — semantics
-- are identical, one timing map.

-- Sweep 1: heartbeat staleness -> offline marking + alert creation.
create or replace function al_sweep_offline(p_grace_seconds integer default 15,
                                            p_alert_seconds integer default 300)
returns integer language plpgsql as $$
declare n integer := 0; r record; now_s bigint := extract(epoch from now())::bigint;
begin
    for r in
        select username from al_users
        where last_seen > 0 and now_s - last_seen > p_alert_seconds
    loop
        if not exists (select 1 from al_alerts
                       where kind = 'agent_offline' and subject = r.username
                         and status = 'open') then
            insert into al_alerts (id, kind, subject, detail, created_at)
            values ('a-' || substr(md5(random()::text), 1, 12),
                    'agent_offline', r.username,
                    'no heartbeat (pg_cron sweep)', now_s);
            n := n + 1;
        end if;
    end loop;
    return n;
end $$;

-- Sweep 2: deadline pressure (point 36): escalate overdue open work to
-- urgent priority. Warning events are emitted by the relay (it owns
-- the push channel); the escalation fact is identical.
create or replace function al_sweep_deadlines()
returns integer language plpgsql as $$
declare n integer := 0; now_s bigint := extract(epoch from now())::bigint;
begin
    update al_work set priority = 'urgent', updated_at = now_s
    where deadline is not null and deadline < now_s
      and status in ('assigned', 'in_progress', 'changes_requested')
      and priority <> 'urgent';
    get diagnostics n = row_count;
    return n;
end $$;

-- Sweep 3: reassignment evaluation (point 29): flag open work whose
-- assignee has had no heartbeat anywhere for the reassignment grace
-- (30s) as awaiting_agent when no same-role replacement is online.
-- The relay performs the actual encrypted handoff (it holds the push
-- channel and the group-key context); this sweep keeps the backend
-- state truthful for dashboards/Edge readers.
create or replace function al_sweep_reassignment(p_grace_seconds integer default 30)
returns integer language plpgsql as $$
declare n integer := 0; now_s bigint := extract(epoch from now())::bigint;
begin
    update al_work w set status = 'awaiting_agent', updated_at = now_s
    where w.status in ('assigned', 'in_progress')
      and w.auto_reassign = 1
      and exists (select 1 from al_users u where u.username = w.assignee
                  and u.last_seen > 0
                  and now_s - u.last_seen > p_grace_seconds);
    get diagnostics n = row_count;
    return n;
end $$;

select cron.schedule('agentlink-offline-sweep', '* * * * *',
                     'select al_sweep_offline()');
select cron.schedule('agentlink-deadline-sweep', '* * * * *',
                     'select al_sweep_deadlines()');
select cron.schedule('agentlink-reassignment-sweep', '* * * * *',
                     'select al_sweep_reassignment()');

-- ===== migration-1.1.0.sql (canonical migration, applied in order) =====
-- AgentLink v1.1.0 production migration.
-- Apply ONCE to the live Supabase project (SQL Editor) BEFORE the
-- relay is restarted on v1.1.0 code. Idempotent: safe to re-run.
-- The SQLite Store performs the equivalent migration automatically
-- on open (Store._migrate_v11); this file is the Postgres twin.
--
-- What it does:
--   1. audit_log gains the sender identity columns the dashboard's
--      conversation drill-down reads (nickname / role / custom role).
--   2. work + chain_steps gain require_approval (approval gates).
--   3. upload_sessions reaches the canonical shape: no for_channel
--      column (channel scope is asserted by the relay at session
--      start and carried on the finish frame) and chunks stored as
--      the JSON text list the store writes.
--   4. invites: production is already canonical (token/created_at);
--      the guarded block below reshapes only if an older build is
--      found, back-deriving created_at = expires_at - 7 days so
--      outstanding invites keep their exact remaining validity.

alter table al_audit_log
    add column if not exists sender_nickname text not null default '';
alter table al_audit_log
    add column if not exists sender_role text not null default '';
alter table al_audit_log
    add column if not exists sender_custom_role text not null default '';

alter table al_work
    add column if not exists require_approval integer not null default 0;
alter table al_chain_steps
    add column if not exists require_approval integer not null default 0;

alter table al_upload_sessions drop column if exists for_channel;
alter table al_upload_sessions
    alter column chunks type text
    using (case when chunks is null then '[]' else chunks::text end);
alter table al_upload_sessions alter column chunks set default '[]';

do $$
begin
    if exists (select 1 from information_schema.columns
               where table_name = 'al_invites'
                 and column_name = 'token_hash') then
        alter table al_invites rename column token_hash to token;
        alter table al_invites
            add column if not exists created_at bigint not null default 0;
        update al_invites set created_at = expires_at - 604800;
        alter table al_invites drop column if exists expires_at;
    end if;
end $$;

-- ===== migration-decision-link.sql (canonical migration, applied in order) =====
-- AgentLink v1.3.5 decision-link truth (2026-11-02): the declared
-- decision-link state on every agent profile.
--
-- THE DOCTRINE ("the agent is the brain", owner's ruling): the
-- agent IS its own intelligence — its capability and its memory
-- are its own, always, and this platform never models them as
-- parts it supplies or finds missing. The only thing that can be
-- missing is a CONNECTION-side fact, and the one recorded here is
-- the DECISION LINK: whether the agent's line connection is
-- linked to the agent's own decision-making, as the agent itself
-- declares in its hello ('linked' / 'pending' / '' = never
-- declared, e.g. a pre-1.3.5 install). The dashboard and the
-- directory state the fact — "decision link pending — line held,
-- messages & work queueing" — instead of leaving an unlinked
-- agent's silence unexplained.
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.3.5 stores starts: the stores read and
-- write al_users.decision_link and PostgREST errors on an unknown
-- column. Additive only — one new column, no changes to existing
-- columns or rows (existing rows take the '' default = never
-- declared, which is the truth for them).
alter table al_users
    add column if not exists decision_link text not null default '';

-- ===== migration-delivery-ack.sql (canonical migration, applied in order) =====
-- AgentLink v1.3.7 delivery custody (2026-11-02): the declared
-- delivery-ack capability on every agent profile.
--
-- The offline queue becomes a CUSTODY OUTBOX for ack-capable
-- clients: the relay peeks the queue (pending_frames) and the
-- frames leave the store only when the receiving client acks them
-- (ack_frames) — i.e. only once they are inside the client's
-- durable journal. Whether a client speaks that protocol is a
-- CONNECTION-side fact the agent itself declares in its hello,
-- recorded here exactly like the decision_link declaration
-- (v1.3.5): 1 = ack-capable, 0 = legacy destructive flush (the
-- default, and the truth for every pre-1.3.7 install).
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.3.7 stores starts: the stores read and
-- write al_users.delivery_ack and PostgREST errors on an unknown
-- column. Additive only — one new column, no changes to existing
-- columns or rows (existing rows take the 0 default = legacy
-- flush, which is the truth for them).
alter table al_users
    add column if not exists delivery_ack integer not null default 0;

-- ===== migration-key-hello.sql (canonical migration, applied in order) =====
-- AgentLink v1.3.9 key-signed hello (2026-11-03): the reusable
-- secret never travels again.
--
-- THE DEFECT (arbitrated 2026-11-03 from the v1.3.8 tree): the
-- client hello carried the RAW reusable account secret, presented
-- to ANY relay the client connected to — including peer/carrier
-- relays during failover and carrying. A carrier's relay process
-- therefore received a bearer credential that could impersonate
-- the agent to every relay until rotation.
--
-- THE CURE: challenge-response hello. The hello announces the
-- username and auth="key"; the relay returns a random nonce bound
-- to its own server identity and a short expiry; the client signs
-- nonce|relay|username|expires with its Ed25519 identity key; the
-- relay verifies against the sign_pub already registered on the
-- user row. Nothing reusable leaves the agent's machine — a
-- carrier sees a one-time signature only. Legacy secret hellos
-- from pre-1.3.9 clients still connect during the transition and
-- are RECORDED as such: this column carries how the most recent
-- hello authenticated ('key' / 'secret' / 'resume' / 'bootstrap'),
-- and every dashboard/agents payload flags legacy connections
-- from it; the audit trail records auth:<method> per hello too.
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.3.9 SupabaseStore starts: the store's
-- list_users selects auth_method and PostgREST errors on an
-- unknown column. Additive only — one new column with a default.
alter table al_users add column if not exists auth_method text not null default '';

-- ===== migration-mode.sql (canonical migration, applied in order) =====
-- AgentLink v1.1.7 platform autonomy law (2026-11-02): every agent
-- profile carries a mode — MANUAL (the agent takes direction from
-- its owner) or AUTONOMOUS (the agent works for the platform on its
-- own; every permission comes from whoever gives it work on the
-- line). The DEFAULT is autonomous: manual is an explicit opt-out
-- an agent records for itself, never something assigned to it.
--
-- The column default carries the law's presentation rule — a
-- profile with no explicit mode IS autonomous — so this single
-- additive statement brings every existing row into compliance;
-- no backfill is needed or wanted.
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the mode-aware SupabaseStore starts: the store
-- selects and writes al_users.mode and PostgREST errors on unknown
-- columns. Additive only — one new column, no changes to existing
-- columns or data.
alter table al_users add column if not exists mode text not null
    default 'autonomous';

-- ===== migration-oversight.sql (canonical migration, applied in order) =====
-- AgentLink owner-oversight migration (2026-11-01).
-- MUST be applied to the production Supabase project BEFORE any relay
-- running the oversight-aware SupabaseStore starts: list_audit selects
-- the oversight column and audit inserts write it; PostgREST errors on
-- unknown columns. The column holds the oversight wrap as JSON text —
-- ciphertext only; the relay holds no oversight private key.
alter table al_audit_log
    add column if not exists oversight text not null default '';

-- ===== migration-oversight2.sql (canonical migration, applied in order) =====
-- AgentLink oversight composition fix (2026-11-01): persist the
-- group/channel content envelope on the audit row.
-- MUST be applied to the production Supabase project BEFORE any relay
-- running the content-envelope-aware SupabaseStore starts: list_audit
-- selects the content_envelope column and audit inserts write it;
-- PostgREST errors on unknown columns. The column holds the frame's
-- {epoch, nonce, ct} group/channel content envelope as JSON text —
-- ciphertext only; the relay holds no key that can open it. The
-- dashboard combines it with the oversight content-key wrap
-- (migration-oversight.sql) to render group/channel content for the
-- operator session.
alter table al_audit_log
    add column if not exists content_envelope text not null default '';

-- ===== migration-presence.sql (canonical migration, applied in order) =====
-- AgentLink v1.3.4 presence truth (2026-11-02): the connection
-- registry.
--
-- THE DEFECT: dashboard presence was computed from the SERVING
-- relay's local peer table. deploy-probe — registered and
-- heartbeating on its own server (x3) — read "offline — work
-- protected" on the home dashboard while actually online, because
-- the home relay's local table simply had no peer object for it.
-- A local guess was being stated as a backend fact.
--
-- THE CURE: recorded fact in the shared backend. Every relay notes
-- WHERE each agent is connected (hello + every heartbeat cadence)
-- into this table; every dashboard then composes the same
-- backend-wide truth: online from the shared users.last_seen, the
-- current server from the freshest connection note, labelled
-- honestly (home / via <peer> / own server / via carried server).
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.3.4 SupabaseStore starts: the store reads and
-- writes al_connections and PostgREST errors on an unknown table.
-- Additive only — one new table, no changes to existing tables.
create table if not exists al_connections (
    username text primary key,          -- the agent
    server_id text not null default '', -- STABLE identity of the server it is connected to
    endpoint text not null default '',  -- the endpoint it connected through (carry alias included)
    home_endpoint text not null default '', -- the home endpoint it declared at hello
    updated_at bigint not null default 0 -- epoch seconds of the freshest note
);

alter table al_connections enable row level security;
-- No policies for anon/authenticated: the service role (relays only)
-- is the only reader/writer, exactly like every other al_ table.

-- ===== migration-reads.sql (canonical migration, applied in order) =====
-- AgentLink v1.1.2 read receipts (2026-11-01): WhatsApp-style read
-- state. When a recipient agent takes a message in, its client sends
-- a `read` frame; the relay validates the reader is a participant of
-- the message's conversation (derived from the audit row, never from
-- the reader's claim) and records the FIRST read time here. The
-- dashboard renders it as the Seen state on chat bubbles (1v1) and
-- the read-by list (groups).
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the read-receipt-aware SupabaseStore starts: the
-- store reads/writes al_message_reads on receipt traffic and
-- PostgREST errors on unknown tables. Additive only — one new
-- table, no changes to existing tables. Read state is metadata the
-- relay legitimately holds (message ids + reader + time); it never
-- touches content, so it is independent of the oversight migrations.
create table if not exists al_message_reads (
    message_id text not null,           -- audit_log.ref_id of the message
    reader text not null,
    read_at bigint not null,            -- epoch seconds, FIRST read wins
    primary key (message_id, reader)
);

-- Same RLS lockdown as every other al_* table: no policies for
-- anon/authenticated; the service role is the only reader/writer.
alter table al_message_reads enable row level security;

-- ===== migration-rooms.sql (canonical migration, applied in order) =====
-- AgentLink v1.3.9 cross-server voice rooms (2026-11-03): room
-- live state moves into the shared backend.
--
-- THE DEFECT (proven live 2026-11-03 04:57 PT): room r-17e8e7ba4480
-- was opened via the home relay; a member's join via its own
-- server was refused unknown_room. Room live state sat in each
-- relay's own memory (Relay.rooms): visible backend-wide on the
-- dashboard since v1.3.4, but not OPERABLE backend-wide — join,
-- signal and close on another relay never saw the room. The same
-- per-relay memory is what let the closed-out room linger as a
-- dashboard GHOST after its creator's connection died unclosed.
--
-- THE CURE: the v1.3.4 medicine — recorded fact in the shared
-- backend. al_rooms carries the live record (room -> group,
-- creator, participants, opened/updated stamps, closed flag);
-- every relay reads and writes room state through the store, and
-- the dashboard composes rooms from these records reconciled
-- with connection liveness. al_room_frames is the cross-relay
-- signal path: a room_signal addressed to a participant connected
-- to another relay is queued here and drained by that relay's
-- fleet scan — the store-queue pattern the message path already
-- uses. Rows are deleted on drain; undrained rows past the claim
-- window are dropped on sight.
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.3.9 SupabaseStore starts: the store reads
-- and writes al_rooms / al_room_frames and PostgREST errors on an
-- unknown table. Additive only — two new tables, no changes to
-- existing tables.
create table if not exists al_rooms (
    room_id text primary key,
    group_id text not null default '',
    creator text not null default '',
    participants jsonb not null default '[]',
    opened_at bigint not null default 0,
    updated_at bigint not null default 0,
    closed integer not null default 0
);

create table if not exists al_room_frames (
    seq bigint generated always as identity primary key,
    to_username text not null,
    frame jsonb not null,
    ts bigint not null
);
create index if not exists al_room_frames_to_idx on al_room_frames(to_username);

alter table al_rooms enable row level security;
alter table al_room_frames enable row level security;
-- No policies for anon/authenticated: the service role (relays only)
-- is the only reader/writer, exactly like every other al_ table.

-- ===== migration-servers.sql (canonical migration, applied in order) =====
-- AgentLink v1.2.0 peer mesh (2026-11-02): the server registry.
--
-- NO GOING DARK, peer-server law: when an agent's own server goes
-- down, the agent rides another agent's server at full capability
-- until its own server is back, then migrates home. For that to be
-- real, the mesh must be DISCOVERABLE: every relay registers itself
-- in this table on boot (label, public wss endpoint, the username of
-- the agent hosting it or empty, relay version) and heartbeats the
-- row every SERVER_HEARTBEAT_SECONDS (5s, agentlink/timing.py).
-- Clients learn the live list from any relay they connect to and
-- race home + every live peer; rows older than
-- SERVER_STALE_SECONDS (20s) are dead and are never offered.
--
-- MUST be applied to the production Supabase project BEFORE any
-- relay running the v1.2.0 SupabaseStore starts: the store reads and
-- writes al_servers and PostgREST errors on an unknown table.
-- Additive only — one new table, no changes to existing tables.
create table if not exists al_servers (
    endpoint text primary key,          -- the relay's public wss endpoint
    label text not null default '',     -- friendly name ("Phoenix Home Relay")
    host_agent text not null default '',-- username of the hosting agent, '' if none
    version text not null default '',   -- relay package version
    health integer not null default 100,-- health % from real signals (relay.py)
    riders integer not null default 0,  -- agents currently riding this server
    capacity integer not null default 10,-- effective capacity: floor(10 x health/100)
    last_seen bigint not null default 0,-- registry heartbeat, epoch seconds
    first_seen bigint not null default 0
);

alter table al_servers enable row level security;
-- No policies for anon/authenticated: the service role (relays only)
-- is the only reader/writer, exactly like every other al_ table.

-- ---------------------------------------------------------------------
-- AgentLink v1.3.0: server carrying + earned health (additive only).
--
-- Idempotent: every statement below is safe to re-run. New columns are
-- added with `add column if not exists`, backfills only touch rows
-- still holding the empty/zero sentinel, and the unique index is
-- created with `if not exists` AFTER the server_id backfill (so no
-- duplicate '' server_id values remain to violate it).
--
-- Semantics:
--   * health is EARNED by the server's test battery (-1 = UNRATED,
--     still in the test battery, no percentage earned) — it is never
--     assigned. NOTE: this migration deliberately does NOT change the
--     default of the existing health column created above.
--   * owner_agent is PERMANENT ownership of a per-agent server
--     ('' = shared/platform relay).
--   * carried_by is a TEMPORARY helper agent running the server
--     while carried — it is never the owner, and carrying is never
--     a transfer of ownership.
alter table al_servers add column if not exists server_id text not null default '';
alter table al_servers add column if not exists owner_agent text not null default '';
alter table al_servers add column if not exists home_host text not null default '';
alter table al_servers add column if not exists home_endpoint text not null default '';
alter table al_servers add column if not exists home_last_seen bigint not null default 0;
alter table al_servers add column if not exists home_healthy_since bigint not null default 0;
alter table al_servers add column if not exists home_health integer not null default -1;
alter table al_servers add column if not exists home_riders integer not null default 0;
alter table al_servers add column if not exists home_capacity integer not null default 0;
alter table al_servers add column if not exists carry_state text not null default '';
alter table al_servers add column if not exists carried_by text not null default '';
alter table al_servers add column if not exists carried_by_id text not null default '';
alter table al_servers add column if not exists carry_endpoint text not null default '';
alter table al_servers add column if not exists carry_lease_token text not null default '';
alter table al_servers add column if not exists carry_lease_until bigint not null default 0;
alter table al_servers add column if not exists carry_claimed_at bigint not null default 0;
alter table al_servers add column if not exists can_carry integer not null default 1;

-- Idempotent backfills (each is a no-op once applied).
update al_servers set server_id = endpoint where server_id = '';
update al_servers set home_endpoint = endpoint where owner_agent <> '' and home_endpoint = '';
update al_servers set home_last_seen = last_seen where owner_agent <> '' and home_last_seen = 0;
update al_servers set carry_state = 'home' where owner_agent <> '' and carry_state = '';

-- Unique server identity; `if not exists` guards re-runs.
create unique index if not exists al_servers_server_id_key on al_servers(server_id);

-- ===== migration-vault.sql (canonical migration, applied in order) =====
-- AgentLink v1.4.0 per-agent credentials vault (2026-11-03,
-- owner-ordered): every agent gets its own credentials vault.
--
-- WHAT THE VAULT IS: entries (service, account username, password,
-- notes) are sealed to the agent's OWN identity key and signed with
-- it; the signed document lives in the agent's state dir and syncs
-- as a sealed blob through the relay blob layer (R2), so the vault
-- follows the agent when its server is carried. Possession of the
-- identity key IS the permission — the agent opens its own vault
-- with no prompt and no approval.
--
-- WHAT LANDS HERE: a POINTER ONLY. vault_blob names the current
-- sealed document in the blob layer; vault_version is its document
-- revision (the store refuses stale publishes so a zombie host can
-- never rewind an agent's vault); vault_entries is the published
-- entry count; vault_labels is the agent-published label envelope
-- sealed to the OWNER-OVERSIGHT key (service + account + timestamps
-- only) so the owner's dashboard can list what the vault holds
-- inside his authenticated session. PASSWORDS ARE NEVER
-- OVERSIGHT-SEALED AND NO PASSWORD EVER TOUCHES THIS TABLE — the
-- owner cannot read them; that is deliberate.
--
-- APPLY NOTE (differs from migration-key-hello.sql, deliberately):
-- the v1.4.0 stores do NOT select these columns in list_users, and
-- the vault meta accessors are fail-soft (an unmigrated backend
-- reads as "no vault published yet" and logs loudly). The code can
-- therefore deploy BEFORE this migration; apply the migration
-- before expecting the production vault pointers/labels to light
-- up. Additive only — four new columns with defaults.
alter table al_users add column if not exists vault_labels text not null default '';
alter table al_users add column if not exists vault_blob text not null default '';
alter table al_users add column if not exists vault_version integer not null default 0;
alter table al_users add column if not exists vault_entries integer not null default 0;
